<!DOCTYPE html><html><head><meta charset="utf-8" /><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?php echo _l('recruitment_form'); ?></title><?php app_external_form_header($form); ?><?php hooks()->do_action('app_web_to_lead_form_head'); ?><style>:root{--sc-green:#169179;--sc-orange:#f7941d;--sc-dark:#111827;--sc-border:#d8e2ec}body.web-to-lead{background:linear-gradient(135deg,#0f172a 0%,#132d3a 45%,#f7941d 160%);font-family:Arial,Helvetica,sans-serif;color:#172033;min-height:100vh}.sc-application-wrap{max-width:980px;margin:28px auto;padding:0 14px}.sc-application-card{background:#fff;border-radius:22px;box-shadow:0 22px 65px rgba(0,0,0,.28);overflow:hidden}.sc-application-header{position:relative;padding:34px;background:linear-gradient(135deg,#0f172a,#169179);color:#fff}.sc-brand-row{display:flex;align-items:center;gap:14px;position:relative;z-index:2}.sc-logo-circle{width:58px;height:58px;border-radius:16px;background:#fff;display:flex;align-items:center;justify-content:center;box-shadow:0 12px 24px rgba(0,0,0,.16);font-weight:900;color:var(--sc-green);font-size:24px}.sc-application-header h1{font-size:30px;line-height:1.2;margin:0 0 7px;font-weight:800}.sc-application-header p{margin:0;opacity:.94;font-size:15px;max-width:720px}.sc-application-body{padding:30px 34px}.sc-application-body .form-group{margin-bottom:17px}.sc-application-body label{font-weight:700;color:#243044;margin-bottom:7px;display:block}.sc-application-body .form-control{border-radius:10px;border:1px solid #cfd6e4;min-height:42px;box-shadow:none}.sc-resume-box{border:1px dashed #93a4bb;border-radius:16px;padding:18px;background:#f8fafc;margin:10px 0 22px}.sc-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:14px}.sc-actions .btn{border-radius:999px;padding:10px 20px;font-weight:800}.sc-actions .btn-success{background:var(--sc-green);border-color:var(--sc-green)}.sc-success-box{border-radius:18px;padding:24px;background:#f0fdf4;border:1px solid #bbf7d0;color:#14532d;box-shadow:0 12px 25px rgba(22,145,121,.15)}.sc-success-box h3{margin-top:0;font-size:24px;font-weight:800;color:#166534}.sc-success-box .btn{border-radius:999px;margin:5px 5px 0 0}@media(max-width:767px){.sc-application-wrap{margin:10px auto;padding:10px}.sc-application-header{padding:24px 18px}.sc-application-header h1{font-size:23px}.sc-application-body{padding:20px 18px}.sc-actions{display:block}.sc-actions .btn{width:100%;margin:5px 0}.sc-brand-row{align-items:flex-start}.sc-logo-circle{width:48px;height:48px}}</style></head>
<body class="web-to-lead <?php echo new_html_entity_decode($form->form_key); ?>"<?php if(is_rtl(true)){ echo ' dir="rtl"';} ?>><div class="sc-application-wrap"><div class="sc-application-card"><div class="sc-application-header"><div class="sc-brand-row"><div class="sc-logo-circle">SC</div><div><h1><?php echo isset($form->name) && $form->name ? new_html_entity_decode($form->name) : 'Smart Choice Job Application'; ?></h1><p>Apply with Smart Choice Contractors USA. Upload your resume, construction experience, certifications, and contact information. Our hiring team will review your application.</p></div></div></div><div class="sc-application-body"><div id="response"></div><?php echo form_open_multipart($this->uri->uri_string(),array('id'=>$form->form_key,'class'=>'disable-on-submit')); ?><?php echo form_hidden('key',$form->form_key); ?><?php echo form_hidden('rec_campaignid', $rec_campaignid); ?><div class="row"><?php $has_file_input=false;if(isset($form_fields)&&is_array($form_fields)){foreach($form_fields as $field){if(isset($field->type)&&$field->type==='file'){$has_file_input=true;}render_form_builder_field($field);}} ?><?php if(!$has_file_input){ ?><div class="col-md-12"><div class="sc-resume-box form-group"><label for="file-input"><i class="fa fa-cloud-upload"></i> Upload Resume, Certifications, Work Photos, or Work History</label><input type="file" name="file-input[]" id="file-input" class="form-control" multiple accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.heic,.txt"><small class="text-muted">Accepted: PDF, Word, JPG, PNG, HEIC, TXT. You may upload more than one file.</small></div></div><?php } ?><?php if(get_option('recaptcha_secret_key')!=''&&get_option('recaptcha_site_key')!=''&&isset($form->recaptcha)&&$form->recaptcha==1){ ?><div class="col-md-12"><div class="form-group"><div class="g-recaptcha" data-sitekey="<?php echo get_option('recaptcha_site_key'); ?>"></div><div id="recaptcha_response_field" class="text-danger"></div></div></div><?php } ?><?php if(is_gdpr()&&get_option('gdpr_enable_terms_and_conditions_lead_form')==1){ ?><div class="col-md-12"><div class="checkbox chk"><input type="checkbox" name="accept_terms_and_conditions" required="true" id="accept_terms_and_conditions" <?php echo set_checkbox('accept_terms_and_conditions','on'); ?>><label for="accept_terms_and_conditions"><?php echo _l('gdpr_terms_agree', terms_url()); ?></label></div></div><?php } ?><div class="clearfix"></div><div class="col-md-12 sc-actions submit-btn-wrapper"><?php if(is_numeric($rec_campaignid)&&$rec_campaignid!=0){ ?><a href="<?php echo site_url('recruitment/recruitment_portal/job_detail/'.$rec_campaignid); ?>" class="btn btn-default"><?php echo _l('cancel'); ?></a><?php } ?><button class="btn btn-success" id="form_submit" type="submit"><i class="fa fa-paper-plane"></i> <?php echo isset($form->submit_btn_name)&&$form->submit_btn_name ? new_html_entity_decode($form->submit_btn_name) : 'Submit Application'; ?></button></div></div><?php echo form_close(); ?></div></div></div><?php app_external_form_footer($form); ?><?php require 'modules/recruitment/assets/js/channel_form_js.php';?><script>(function(){var response=document.getElementById('response');if(!response){return;}var observer=new MutationObserver(function(){var txt=response.innerText||'';if(txt.length>5&&txt.toLowerCase().indexOf('thank')!==-1){response.innerHTML='<div class="sc-success-box"><h3>Thank you for applying!</h3><p>Your application and uploaded files were submitted successfully. Smart Choice Contractors USA will review your information and contact you if your experience matches the position.</p><a class="btn btn-success" href="<?php echo site_url('recruitment/recruitment_portal'); ?>">View Open Positions</a><a class="btn btn-default" href="<?php echo site_url(); ?>">Return To Website</a></div>';window.scrollTo({top:0,behavior:'smooth'});}});observer.observe(response,{childList:true,subtree:true,characterData:true});})();</script><?php hooks()->do_action('app_web_to_lead_form_footer'); ?></body></html>
